import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).parent.parent.parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.wavelet_selection_tests.urp_discrminability.wavelet_evaluator import WaveletEvaluator

#note that no such file exists, it needs to be first generated by running main.py
RESULTS_JSON = PROJECT_ROOT / 'data_container' / 'data' / 'results' / 'urp_discrminability' / 'wavelet_selection_results.json'
OUTPUT_JSON = PROJECT_ROOT / 'data_container' / 'data' / 'results' / 'urp_discrminability' / 'wavelet_statistical_tests.json'

def main():
    """Run Friedman test and pairwise Wilcoxon tests on wavelet results."""

    stats = WaveletEvaluator.perform_statistical_tests_from_json(
        json_path=RESULTS_JSON,
        alpha=0.05,
        output_path=OUTPUT_JSON
    )
    print(f"results saved to: {OUTPUT_JSON}")

if __name__ == '__main__':
    main()
